import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_ops_kernel(const float* input, float* output, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float x = input[idx];
        float sigmoid_x = 1.0f / (1.0f + expf(-x));
        float swish = x * sigmoid_x;
        swish /= 2.0f;
        swish = fmaxf(fminf(swish, 1.0f), -1.0f);
        float tanh_val = tanhf(swish);
        output[idx] = fmaxf(fminf(tanh_val, 1.0f), -1.0f);
    }
}

torch::Tensor fused_operations_cuda(torch::Tensor input) {
    auto num_elements = input.numel();
    auto output = torch::empty_like(input);

    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    fused_ops_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements
    );

    return output;
}
"""

fused_ops_cpp_source = "torch::Tensor fused_operations_cuda(torch::Tensor input);"

fused_ops = load_inline(
    name='fused_ops',
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=['fused_operations_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, bias=True):
        super(ModelNew, self).__init__()
        self.gemm = nn.Linear(in_features, out_features, bias=bias)
        self.fused_ops = fused_ops

    def forward(self, x):
        x = self.gemm(x)
        x = self.fused_ops.fused_operations_cuda(x)
        return x
